import React from 'react';
import './Portfolio.css';

const portfolioItems = [
  {
    title: 'Wedding Photography',
    image: '/GI_logo.png',
    description: 'Capturing the most precious moments of your special day.'
  },
  {
    title: 'Corporate Events',
    image: '/GI_logo.png',
    description: 'Professional coverage for your business events and conferences.'
  },
  {
    title: 'Creative Portraits',
    image: '/GI_logo.png',
    description: 'Unique and artistic portraits tailored to your style.'
  },
  {
    title: 'Product Shoots',
    image: '/GI_logo.png',
    description: 'Showcase your products with high-quality, creative imagery.'
  }
];

const Portfolio = () => {
  return (
    <div className="portfolio-bg">
      <div className="portfolio-header">
        <h1>Our Portfolio</h1>
        <p>Explore our recent work and creative projects.</p>
      </div>
      <div className="portfolio-grid">
        {portfolioItems.map((item, idx) => (
          <div className="portfolio-card" key={idx}>
            <img src={item.image} alt={item.title} className="portfolio-img" />
            <h3>{item.title}</h3>
            <p>{item.description}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Portfolio;
